import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:interceptors");

export enum InterceptorPhase {
    REQUEST = "request",
    RESPONSE = "response",
    ERROR = "error",
}

export interface RequestContext {
    url: string;
    method: string;
    headers: Record<string, string>;
    body?: unknown;
    queryParams?: Record<string, unknown>;
    timestamp: number;
    attempt: number;
}

export interface ResponseContext {
    url: string;
    method: string;
    status: number;
    data: unknown;
    headers: Record<string, string>;
    timestamp: number;
    duration: number;
    cached: boolean;
    retries: number;
}

export interface ErrorContext {
    error: Error;
    url: string;
    method: string;
    attempt: number;
    timestamp: number;
    willRetry: boolean;
}

export type RequestInterceptor = (
    context: RequestContext,
) => RequestContext | Promise<RequestContext> | null | undefined;

export type ResponseInterceptor = (context: ResponseContext) => ResponseContext | Promise<ResponseContext>;

export type ErrorInterceptor = (context: ErrorContext) => Error | Promise<Error> | null | undefined;

export interface Interceptor {
    id: string;
    name: string;
    phase: InterceptorPhase;
    priority: number;
    enabled: boolean;
}

export interface RequestInterceptorConfig extends Interceptor {
    handler: RequestInterceptor;
}

export interface ResponseInterceptorConfig extends Interceptor {
    handler: ResponseInterceptor;
}

export interface ErrorInterceptorConfig extends Interceptor {
    handler: ErrorInterceptor;
}

/**
 * Generate a secure identifier with sufficient entropy
 * Uses 16 bytes (128 bits) of cryptographically secure random data
 * @param prefix - A prefix for the identifier (e.g., 'req', 'res', 'err')
 * @returns A secure identifier string
 */
function generateSecureId(prefix: string): string {
    const timestamp = Date.now().toString(36);
    // Increase from 4 bytes (32 bits) to 16 bytes (128 bits) for better security
    const array = new Uint8Array(16);
    crypto.getRandomValues(array);
    const randomPart = Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("");
    return `${prefix}_${timestamp}_${randomPart}`;
}

export class InterceptorRegistry {
    private requestInterceptors: Map<string, RequestInterceptorConfig>;
    private responseInterceptors: Map<string, ResponseInterceptorConfig>;
    private errorInterceptors: Map<string, ErrorInterceptorConfig>;
    private globalConfig: {
        logRequests: boolean;
        logResponses: boolean;
        logErrors: boolean;
        transformErrors: boolean;
    };
    private sortedRequestChain?: RequestInterceptorConfig[];
    private sortedResponseChain?: ResponseInterceptorConfig[];
    private sortedErrorChain?: ErrorInterceptorConfig[];

    public constructor() {
        this.requestInterceptors = new Map();
        this.responseInterceptors = new Map();
        this.errorInterceptors = new Map();
        this.globalConfig = {
            logRequests: false,
            logResponses: false,
            logErrors: true,
            transformErrors: true,
        };
    }

    public addRequestInterceptor(id: string, handler: RequestInterceptor, priority: number = 0, name?: string): string {
        const interceptorId = id || generateSecureId("req");

        this.requestInterceptors.set(interceptorId, {
            id: interceptorId,
            name: name || interceptorId,
            phase: InterceptorPhase.REQUEST,
            priority,
            enabled: true,
            handler,
        });

        this.rebuildRequestChain();
        return interceptorId;
    }

    public addResponseInterceptor(
        id: string,
        handler: ResponseInterceptor,
        priority: number = 0,
        name?: string,
    ): string {
        const interceptorId = id || generateSecureId("resp");

        this.responseInterceptors.set(interceptorId, {
            id: interceptorId,
            name: name || interceptorId,
            phase: InterceptorPhase.RESPONSE,
            priority,
            enabled: true,
            handler,
        });

        this.rebuildResponseChain();
        return interceptorId;
    }

    public addErrorInterceptor(id: string, handler: ErrorInterceptor, priority: number = 0, name?: string): string {
        const interceptorId = id || generateSecureId("err");

        this.errorInterceptors.set(interceptorId, {
            id: interceptorId,
            name: name || interceptorId,
            phase: InterceptorPhase.ERROR,
            priority,
            enabled: true,
            handler,
        });

        this.rebuildErrorChain();
        return interceptorId;
    }

    public removeInterceptor(id: string): boolean {
        return (
            this.requestInterceptors.delete(id) ||
            this.responseInterceptors.delete(id) ||
            this.errorInterceptors.delete(id)
        );
    }

    public enableInterceptor(id: string): boolean {
        const interceptor =
            this.requestInterceptors.get(id) || this.responseInterceptors.get(id) || this.errorInterceptors.get(id);

        if (interceptor) {
            interceptor.enabled = true;
            this.rebuildRequestChain();
            this.rebuildResponseChain();
            this.rebuildErrorChain();
            return true;
        }
        return false;
    }

    public disableInterceptor(id: string): boolean {
        const interceptor =
            this.requestInterceptors.get(id) || this.responseInterceptors.get(id) || this.errorInterceptors.get(id);

        if (interceptor) {
            interceptor.enabled = false;
            this.rebuildRequestChain();
            this.rebuildResponseChain();
            this.rebuildErrorChain();
            return true;
        }
        return false;
    }

    public getInterceptors(phase?: InterceptorPhase): Interceptor[] {
        const result: Interceptor[] = [];

        if (!phase || phase === InterceptorPhase.REQUEST) {
            for (const interceptor of Array.from(this.requestInterceptors.values())) {
                result.push(interceptor);
            }
        }

        if (!phase || phase === InterceptorPhase.RESPONSE) {
            for (const interceptor of Array.from(this.responseInterceptors.values())) {
                result.push(interceptor);
            }
        }

        if (!phase || phase === InterceptorPhase.ERROR) {
            for (const interceptor of Array.from(this.errorInterceptors.values())) {
                result.push(interceptor);
            }
        }

        return result.sort((a, b) => b.priority - a.priority);
    }

    public clearInterceptors(phase?: InterceptorPhase): void {
        if (!phase || phase === InterceptorPhase.REQUEST) {
            this.requestInterceptors.clear();
        }
        if (!phase || phase === InterceptorPhase.RESPONSE) {
            this.responseInterceptors.clear();
        }
        if (!phase || phase === InterceptorPhase.ERROR) {
            this.errorInterceptors.clear();
        }
    }

    public configureGlobal(config: Partial<typeof this.globalConfig>): void {
        this.globalConfig = { ...this.globalConfig, ...config };
    }

    private rebuildRequestChain(): void {
        const sorted = Array.from(this.requestInterceptors.values())
            .filter((i) => i.enabled)
            .sort((a, b) => b.priority - a.priority);
        this["sortedRequestChain"] = sorted;
    }

    private rebuildResponseChain(): void {
        const sorted = Array.from(this.responseInterceptors.values())
            .filter((i) => i.enabled)
            .sort((a, b) => b.priority - a.priority);
        this["sortedResponseChain"] = sorted;
    }

    private rebuildErrorChain(): void {
        const sorted = Array.from(this.errorInterceptors.values())
            .filter((i) => i.enabled)
            .sort((a, b) => b.priority - a.priority);
        this["sortedErrorChain"] = sorted;
    }

    public async processRequest(context: RequestContext): Promise<RequestContext> {
        let currentContext = { ...context };
        const chain =
            this.sortedRequestChain ||
            Array.from(this.requestInterceptors.values())
                .filter((i) => i.enabled)
                .sort((a, b) => b.priority - a.priority);

        for (const interceptor of chain) {
            try {
                const result = await interceptor.handler(currentContext);
                if (result !== undefined && result !== null) {
                    currentContext = result;
                }
            } catch (error) {
                if (this.globalConfig.logErrors) {
                    log.error(`Request interceptor "${interceptor.name}" failed:`, error);
                }
            }
        }

        if (this.globalConfig.logRequests) {
            log.debug("[Interceptor] Request:", {
                url: currentContext.url,
                method: currentContext.method,
                attempt: currentContext.attempt,
            });
        }

        return currentContext;
    }

    public async processResponse(context: ResponseContext): Promise<ResponseContext> {
        let currentContext = { ...context };
        const chain =
            this.sortedResponseChain ||
            Array.from(this.responseInterceptors.values())
                .filter((i) => i.enabled)
                .sort((a, b) => b.priority - a.priority);

        for (const interceptor of chain) {
            try {
                const result = await interceptor.handler(currentContext);
                if (result !== undefined && result !== null) {
                    currentContext = result;
                }
            } catch (error) {
                if (this.globalConfig.logErrors) {
                    log.error(`Response interceptor "${interceptor.name}" failed:`, error);
                }
            }
        }

        if (this.globalConfig.logResponses) {
            log.debug("[Interceptor] Response:", {
                url: currentContext.url,
                status: currentContext.status,
                duration: currentContext.duration,
                cached: currentContext.cached,
            });
        }

        return currentContext;
    }

    public async processError(context: ErrorContext): Promise<Error> {
        let currentError = context.error;
        const chain =
            this.sortedErrorChain ||
            Array.from(this.errorInterceptors.values())
                .filter((i) => i.enabled)
                .sort((a, b) => b.priority - a.priority);

        for (const interceptor of chain) {
            try {
                const result = await interceptor.handler(context);
                if (result !== undefined && result !== null) {
                    currentError = result;
                    context.error = result;
                }
            } catch (error) {
                if (this.globalConfig.logErrors) {
                    log.error(`Error interceptor "${interceptor.name}" failed:`, error);
                }
            }
        }

        if (this.globalConfig.logErrors) {
            log.debug("[Interceptor] Error:", {
                error: currentError.message,
                url: context.url,
                method: context.method,
                attempt: context.attempt,
                willRetry: context.willRetry,
            });
        }

        return currentError;
    }
}

export function createAuthInterceptor(accessTokenProvider: () => string | Promise<string>): RequestInterceptor {
    return async (context) => {
        const token = await accessTokenProvider();
        return {
            ...context,
            headers: {
                ...context.headers,
                Authorization: `Bearer ${token}`,
            },
        };
    };
}

export function createLoggingInterceptor(options?: {
    logRequests?: boolean;
    logResponses?: boolean;
    logErrors?: boolean;
    sanitizeHeaders?: string[];
}): {
    request: RequestInterceptor;
    response: ResponseInterceptor;
    error: ErrorInterceptor;
} {
    const sanitizeHeaders = options?.sanitizeHeaders || ["Authorization", "Cookie"];

    const request: RequestInterceptor = async (context) => {
        const sanitizedHeaders = { ...context.headers };
        for (const header of sanitizeHeaders) {
            if (sanitizedHeaders[header]) {
                sanitizedHeaders[header] = "[REDACTED]";
            }
        }

        log.debug("[Request]", {
            url: context.url,
            method: context.method,
            headers: sanitizedHeaders,
            body: context.body,
            attempt: context.attempt,
        });

        return context;
    };

    const response: ResponseInterceptor = async (context) => {
        log.debug("[Response]", {
            url: context.url,
            status: context.status,
            duration: `${context.duration}ms`,
            cached: context.cached,
        });

        return context;
    };

    const error: ErrorInterceptor = async (context) => {
        log.error("[Error]", {
            error: context.error.message,
            url: context.url,
            method: context.method,
            attempt: context.attempt,
            willRetry: context.willRetry,
        });

        return context.error;
    };

    return { request, response, error };
}

export function createRetryLoggingInterceptor(): ErrorInterceptor {
    return async (context) => {
        if (context.attempt > 1) {
            log.warn(`[Retry] Attempt ${context.attempt} for ${context.method} ${context.url}`);
        }
        return context.error;
    };
}

export function createResponseTransformInterceptor<T = unknown>(
    transform: (data: T, context: ResponseContext) => T,
): ResponseInterceptor {
    return async (context) => {
        if (context.data && typeof context.data === "object") {
            const transformed = transform(context.data as T, context);
            return {
                ...context,
                data: transformed,
            };
        }
        return context;
    };
}

export function createRequestTimeoutInterceptor(maxTimeout: number): RequestInterceptor {
    return async (context) => {
        return {
            ...context,
            headers: {
                ...context.headers,
                "X-Request-Timeout": maxTimeout.toString(),
            },
            timestamp: Date.now(),
        };
    };
}

export const defaultInterceptors = {
    createAuthInterceptor,
    createLoggingInterceptor,
    createRetryLoggingInterceptor,
    createResponseTransformInterceptor,
    createRequestTimeoutInterceptor,
};
